import { z } from 'zod';

// Client request to generate flashcards
export const FlashcardGenerateRequestSchema = z.object({
  documentId: z.string().min(1, 'documentId is required'),
  topic: z.string().min(2, 'Topic must be at least 2 characters').max(100),
  numberOfCards: z.coerce.number().int().min(1).max(30).default(5),
});

// Single Flashcard item generated by LLM / Dify Workflow
export const FlashcardItemSchema = z.object({
  front: z.string().min(3, 'Card front must be a clear concept or question'),
  back: z.string().min(3, 'Card back must be a concise grounded explanation'),
});

// Entire Structured output from Dify Workflow
export const FlashcardWorkflowOutputSchema = z.object({
  title: z.string().min(2).default('Study Deck'),
  cards: z.array(FlashcardItemSchema).min(1, 'At least 1 card is required'),
});

// Client request to update card review status
export const FlashcardUpdateStatusSchema = z.object({
  status: z.enum(['NEW', 'KNOWN', 'NEED_REVISION']),
});

export type FlashcardGenerateRequestInput = z.infer<typeof FlashcardGenerateRequestSchema>;
export type FlashcardItem = z.infer<typeof FlashcardItemSchema>;
export type FlashcardWorkflowOutput = z.infer<typeof FlashcardWorkflowOutputSchema>;
export type FlashcardUpdateStatusInput = z.infer<typeof FlashcardUpdateStatusSchema>;

/**
 * Robust JSON extraction helper for flashcard workflow outputs
 */
export function extractAndParseFlashcardJson<T>(rawText: string, schema: z.ZodSchema<T>): T {
  let cleaned = rawText.trim();
  
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  }
  
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }

  const parsed = JSON.parse(cleaned);
  return schema.parse(parsed);
}
